import {loadEarthThermal,EARTH_THERMAL_SOURCE} from './earth-thermal.js';
import {loadPlanetaryThermal,samplePlanetaryThermal} from './planetary-thermal.js';
import {escapeHTML as esc} from './icons.js';

const celsius=k=>Number.isFinite(k)?`${(k-273.15).toFixed(1)} °C`:'Unavailable';
const safeURL=url=>{try{const u=new URL(url);return u.protocol==='https:'?u.href:'';}catch{return '';}};
const link=(url,label)=>safeURL(url)?`<a href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';
export const THERMAL_LIMIT='Thermal records are shown as context. Earth daily means, lunar annual surface maxima and rover observations have different spatial footprints and time sampling. No cross-body temperature score or temperature-based candidate ranking is calculated.';

export function thermalChart(series,label){
  const points=series.filter(p=>Number.isFinite(p.valueK));if(points.length<2)return '';
  const values=points.map(p=>p.valueK),min=Math.min(...values),max=Math.max(...values),span=Math.max(1,max-min),w=600,h=155,p=30;
  const times=series.map(v=>Number.isFinite(v.elapsedSeconds)?v.elapsedSeconds:Number.isFinite(v.lmstSeconds)?v.lmstSeconds:Date.parse(v.time)),timed=times.every(Number.isFinite)&&times.at(-1)>times[0];
  const positions=series.map((v,i)=>Number.isFinite(v.valueK)?`${(p+(timed?(times[i]-times[0])/(times.at(-1)-times[0]):i/Math.max(1,series.length-1))*(w-p*2)).toFixed(1)},${(h-p-(v.valueK-min)/span*(h-p*2)).toFixed(1)}`:null);
  const segments=[];let segment=[];for(const position of positions){if(position)segment.push(position);else if(segment.length){segments.push(segment);segment=[];}}if(segment.length)segments.push(segment);
  return `<svg class="thermal-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}"><title>${esc(label)}; gaps represent missing observations. ${timed?'Time spacing is preserved.':'Horizontal axis is retained sample order, not elapsed time.'}</title><line x1="${p}" x2="${w-p}" y1="${h-p}" y2="${h-p}" stroke="#344b5b"/>${segments.map(s=>s.length===1?`<circle cx="${s[0].split(',')[0]}" cy="${s[0].split(',')[1]}" r="2.5" fill="#66d3c8"/>`:`<polyline fill="none" stroke="#66d3c8" stroke-width="2" points="${s.join(' ')}"/>`).join('')}<text x="${p}" y="14">${esc(celsius(max))}</text><text x="${p}" y="${h-p-5}">${esc(celsius(min))}</text><text x="${p}" y="${h-7}">${esc(series[0].time)}</text><text x="${w-p}" y="${h-7}" text-anchor="end">${esc(series.at(-1).time)}</text></svg>`;
}

function earthContent(r){
  const s=r.summary;if(!s?.validCount)return `<p>${esc(r.error?.message||r.messages?.join(' ')||'No valid surface-temperature values were returned.')}</p>`;
  return `<span class="thermal-badge">MODEL / REANALYSIS · DAILY MEANS</span><p>Earth skin temperature · ${esc(r.actualPeriod.start)} to ${esc(r.actualPeriod.end)} · Local Solar Time</p><div class="thermal-values"><div><strong>${celsius(s.meanOfDailyMeansK)}</strong><small>Mean of valid daily means</small></div><div><strong>${celsius(s.minimumDailyMeanK)}</strong><small>Lowest daily mean · ${esc(s.minimumDailyMeanDate)}</small></div><div><strong>${celsius(s.maximumDailyMeanK)}</strong><small>Highest daily mean · ${esc(s.maximumDailyMeanDate)}</small></div></div><p>${s.validCount} / ${r.requestedPeriod.days} valid days. These are daily averages, not the coldest night or hottest afternoon. Native grid: ${esc(r.source.spatialResolution.latitudeDegrees)}° latitude × ${esc(r.source.spatialResolution.longitudeDegrees)}° longitude; grid-cell context, not the 500 m terrain grid.</p>${thermalChart(r.series,'Earth daily-mean surface skin temperature in Celsius')}`;
}

function planetContent(r){
  if(!r.available)return `<p>${esc(r.reason||r.error?.message||r.messages?.join(' ')||'A validated surface-temperature product is not available here.')}</p>`;
  const s=r.summary||{};
  const description=typeof r.temporal==='string'?r.temporal:r.temporal?.label||JSON.stringify(r.temporal);
  return `<span class="thermal-badge">${esc(r.body==='moon'?'THERMAL MODEL FIT · ANNUAL SURFACE MAXIMUM':'ROVER OBSERVATIONS · LOCAL FOOTPRINT')}</span><p>${esc(r.statistic)} · ${esc(description||'See the source record for observation dates.')}</p><div class="thermal-values"><div><strong>${celsius(s.minK)}</strong><small>${r.raster?'Lowest annual maximum in this window':'Lowest retained observation'}</small></div><div><strong>${celsius(s.maxK)}</strong><small>${r.raster?'Highest annual maximum in this window':'Highest retained observation'}</small></div></div><p>${esc(s.validCount??0)} valid ${r.raster?'grid samples. Annual maxima at different locations do not describe a daily temperature cycle.':'instrument observations. A rover footprint does not map the whole crater.'}</p>${r.coordinates?`<p>Representative rover location: ${esc(r.coordinates.lat)}° N, ${esc(r.coordinates.lon)}° E. ${esc(r.coordinates.note||'')}</p>`:''}${r.temporal?.startUTC?`<p>UTC: ${esc(r.temporal.startUTC)} to ${esc(r.temporal.endUTC)}</p>`:''}${r.temporal?.note?`<p>${esc(r.temporal.note)}</p>`:''}${r.quality?.note?`<p class="thermal-notice">${esc(r.quality.note)}</p>`:''}${r.source?.caveat?`<p>${esc(r.source.caveat)}</p>`:''}${r.series?`<p style="margin-top:12px">Chart: ${r.quality?.binWidthHours?esc(r.quality.binWidthHours*60)+'-minute means of retained measurements':'retained measurements'} · local mean solar time. Gaps are not filled.</p>${thermalChart(r.series,'Local rover surface brightness-temperature: means of retained observations')}`:''}`;
}

export function createThermalUI({getTarget,getEarth,getExpedition,showCompare,toast,loadEarth=loadEarthThermal,loadPlanet=loadPlanetaryThermal}={}){
  const records=new Map(),jobs=new Map();let mission=false,sceneIndex=0,sceneSiteId=null,sceneGeneration=0;
  const usable=r=>r?.body==='earth'?!!r.summary?.validCount:!!r?.available;
  function load(site,{refresh=false}={}){
    if(!site)return Promise.resolve(null);
    if(jobs.has(site.id))return jobs.get(site.id);
    if(records.has(site.id)&&!refresh)return Promise.resolve(records.get(site.id));
    const controller=new AbortController();
    const promise=(async()=>{try{const record=site.body==='earth'?await loadEarth(site,{signal:controller.signal,refresh}):await loadPlanet(site,{signal:controller.signal});records.set(site.id,{...record,body:site.body});}catch(error){records.set(site.id,{siteId:site.id,body:site.body,available:false,status:'error',error:{message:error.message}});}finally{jobs.delete(site.id);render();if(sceneSiteId===site.id)updateScene();}return records.get(site.id);})();
    jobs.set(site.id,promise);render();return promise;
  }
  function card(site){const r=records.get(site.id),pending=jobs.has(site.id);return `<article class="thermal-card"><p class="eyebrow">${site.body==='earth'?'EARTH CANDIDATE':'PLANETARY TARGET'}</p><h3>${esc(site.name)}</h3>${r?(site.body==='earth'?earthContent(r):planetContent(r)):`<p>${pending?'Reading the temperature source…':'Temperature data have not been loaded.'}</p>`}${r?`<details><summary>Source, time coverage &amp; limitations</summary><p>${esc(r.source?.title||r.source?.agency||'Source metadata')}</p>${link(r.source?.requestUrl||r.source?.url||r.source?.dataUrl,'Original data')}${(r.limitations||[]).length?`<ul>${r.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<pre>${esc(JSON.stringify({metric:r.metric,quantity:r.quantity,statistic:r.statistic,temporal:r.temporal,requestedPeriod:r.requestedPeriod,actualPeriod:r.actualPeriod,quality:r.quality,coordinates:r.coordinates,source:r.source,comparability:r.comparability},null,2))}</pre></details>`:''}${r&&!usable(r)?`<button class="button button-outline button-small" data-thermal-retry="${esc(site.id)}" ${pending?'disabled':''}>${pending?'Loading…':'Retry data retrieval'}</button>`:''}</article>`;}
  function render(){
    const host=document.querySelector('#thermal-workspace');if(!host||!getTarget()||!getEarth())return;
    host.innerHTML=`<section class="thermal-panel panel"><div class="thermal-heading"><div><p class="eyebrow">THERMAL ENVIRONMENT STUDY</p><h2>What does the surface temperature tell us?</h2><p>Read each record with its own time coverage and measurement method.</p></div><span class="thermal-badge">${mission?'ACTIVE MISSION OBJECTIVE':'SEPARATE FROM TERRAIN RANKING'}</span></div><div class="thermal-grid">${card(getTarget())}${card(getEarth())}</div><p class="thermal-notice">${THERMAL_LIMIT} A thermal analogy also depends on daily cycles, heat transfer, atmosphere and the equipment being tested.</p></section>`;
    host.querySelectorAll('[data-thermal-retry]').forEach(button=>button.onclick=()=>load([getTarget(),getEarth()].find(s=>s.id===button.dataset.thermalRetry),{refresh:true}));
  }
  function mountComparison(){render();void load(getTarget());void load(getEarth());}
  function selectionChanged(){render();if(mission||document.querySelector('#compare-view:not(.hidden)')){void load(getTarget());void load(getEarth());}}
  function setMission(value){mission=value==='thermal';const prompt=document.querySelector('#thermal-mission-prompt');if(prompt){prompt.classList.toggle('thermal-mission-active',mission);prompt.innerHTML=mission?'Surface temperature is now your study objective. Read thermal records in Compare; the candidate ranking still measures terrain.':'Surface-temperature evidence is available separately in Compare.';const button=document.createElement('button');button.className='text-link';button.textContent='Review thermal evidence ↗';button.onclick=()=>{showCompare();document.querySelector('#thermal-workspace')?.scrollIntoView?.({block:'start',behavior:'smooth'});};prompt.append(button);}selectionChanged();}
  function sourceHTML(){return `<section class="thermal-panel panel"><p class="eyebrow">SURFACE TEMPERATURE</p><h2>Thermal evidence has its own scale</h2><p class="thermal-copy" style="margin-top:12px">Earth records use NASA POWER TS: daily-mean skin temperature from model/reanalysis products, requested for the complete year 2025. They are not 2 m air temperature or satellite temperature maps. Lunar and Martian sources retain their own statistic, footprint and observation period in Compare and in the evidence export.</p><p class="thermal-notice">${THERMAL_LIMIT} No ice detection or robot thermal-survival simulation is implied.</p><div class="source-chips">${link(EARTH_THERMAL_SOURCE?.url||'https://power.larc.nasa.gov/docs/services/api/temporal/daily/','NASA POWER documentation')}${link('https://pds-geosciences.wustl.edu/missions/lro/diviner.htm','LRO Diviner archive')}${link('https://pds-atmospheres.nmsu.edu/data_and_services/atmospheres_data/PERSEVERANCE/meda.html','Mars 2020 atmospheric archive')}</div></section>`;}
  function snapshot(){return {objective:mission?'Thermal environment study':'Terrain study',scope:'Surface thermal context',temperatureRankingApplied:false,comparability:{scoreEligible:false,reason:THERMAL_LIMIT},target:records.get(getTarget().id)||{status:'not-loaded'},candidate:records.get(getEarth().id)||{status:'not-loaded'}};}
  function report(){const r=snapshot();return `\n\n## Surface thermal context\n\n${THERMAL_LIMIT}\n\n${[getTarget(),getEarth()].map(site=>{const record=records.get(site.id);return `### ${site.name}\n\n${record?JSON.stringify({status:record.status,available:record.available,metric:record.metric,statistic:record.statistic,temporal:record.temporal,requestedPeriod:record.requestedPeriod,actualPeriod:record.actualPeriod,summary:record.summary,location:record.location,source:record.source,limitations:record.limitations,comparability:record.comparability},null,2):'Thermal data not loaded. No value inferred.'}`;}).join('\n\n')}\n`;}
  function sceneDescriptor(){
    const exp=getExpedition(),r=records.get(sceneSiteId);if(!exp?.site||exp.site.id!==sceneSiteId||!r)return null;
    if(r.body==='earth'&&r.summary?.validCount){const p=r.series[Math.min(sceneIndex,r.series.length-1)];return {sample:()=>Number.isFinite(p?.valueK)?p.valueK:null,label:`${p?.time}: ${celsius(p?.valueK)} · daily-mean model skin temperature`,detail:'Uniform location context from a coarse NASA POWER grid cell. This is not a spatial temperature map of the 32 km terrain.'};}
    if(r.raster&&r.available)return {sample:(lat,lon)=>{const value=samplePlanetaryThermal(r,lat,lon);return typeof value==='number'?value:value?.valueK??null;},label:'Diviner model-fitted annual maximum surface temperature',detail:'Spatial source values, not live temperature. Different pixels may reach their maximum at different times. Grey indicates missing coverage.'};
    return null;
  }
  function updateScene(){const exp=getExpedition();if(!exp?.site||exp.site.id!==sceneSiteId)return;const host=document.querySelector('#thermal-scene');if(!host)return;const r=records.get(sceneSiteId),descriptor=sceneDescriptor();
    if(descriptor){exp.setThermalField(descriptor);if(exp.layer==='temperature')exp.recolor();host.innerHTML=`<p><strong>${esc(descriptor.label)}</strong></p><div class="thermal-scale"><span>≤ −233 °C</span><i></i><span>≥ 127 °C</span></div><p>${esc(descriptor.detail)}</p>${r.body==='earth'?`<label class="field-label" for="thermal-day">Day in 2025 · ${esc(r.series[sceneIndex]?.time)}</label><input id="thermal-day" type="range" min="0" max="${r.series.length-1}" value="${sceneIndex}" aria-label="Select the Earth daily-mean temperature date">`:''}<button class="text-link" id="scene-thermal-compare">Read full thermal evidence ↗</button>`;host.querySelector('#thermal-day')?.addEventListener('input',e=>{sceneIndex=Number(e.target.value);const selected=sceneDescriptor();exp.setThermalField(selected);host.querySelector('p strong').textContent=selected.label;host.querySelector('label[for=thermal-day]').textContent='Day in 2025 · '+r.series[sceneIndex].time;updateTelemetry(exp.telemetry?.());});}
    else {exp.setThermalField(null);host.innerHTML=`<p><strong>${jobs.has(sceneSiteId)?'Reading temperature data…':'No spatial thermal layer available'}</strong></p><p>${r?.body==='mars'&&r.available&&r.series?.length?'Local rover observations are available in Compare. They cannot be spread across the whole crater.':esc(r?.error?.message||r?.reason||'No source values have been validated for this location. Terrain colours are not used to estimate temperature.')}</p><button class="text-link" id="scene-thermal-compare">Read thermal evidence ↗</button>`;}
    const readout=document.createElement('p');readout.id='thermal-scene-value';readout.style.marginTop='8px';host.append(readout);updateTelemetry(exp.telemetry?.());
    host.querySelector('#scene-thermal-compare').onclick=()=>showCompare();
  }
  async function activateLayer(){const exp=getExpedition();if(!exp?.site)return;const generation=++sceneGeneration;sceneSiteId=exp.site.id;sceneIndex=0;document.querySelector('#thermal-scene')?.classList.remove('hidden');exp.setThermalField(null);exp.setLayer('temperature');updateScene();await load(exp.site);if(generation!==sceneGeneration||exp.layer!=='temperature')return;updateScene();if(!sceneDescriptor())toast?.('No spatial thermal field for this location. Open Compare for available thermal evidence.');}
  function hideLayer(){++sceneGeneration;document.querySelector('#thermal-scene')?.classList.add('hidden');}
  function inspect(info){const r=records.get(info.siteId);if(!r)return null;if(r.body==='earth')return {scope:'Coarse location context, not a local instrument measurement',recordDate:r.series?.[sceneIndex]?.time,valueK:r.series?.[sceneIndex]?.valueK??null,statistic:r.metric?.statistic,source:r.source};if(r.raster)return {scope:'Source thermal field sample',...samplePlanetaryThermal(r,info.lat,info.lon),statistic:r.statistic,source:r.source};return {scope:'No spatial temperature field at this terrain point',available:false};}
  function updateTelemetry(info){const el=document.querySelector('#thermal-scene-value');if(!el||!info)return;const sample=inspect(info);el.textContent=Number.isFinite(sample?.valueK)?`${celsius(sample.valueK)} · ${sample.recordDate||'annual surface maximum at this source sample'}`:'No spatial temperature value at this location.';}
  function inspectionHTML(info){const sample=inspect(info);if(!sample)return '';return `<div class="thermal-notice"><strong>Surface thermal context: ${celsius(sample.valueK)}</strong><p>${esc(sample.scope)}${sample.recordDate?' · '+esc(sample.recordDate):''}. ${esc(sample.statistic||'No mapped temperature statistic available.')}</p></div>`;}
  return {mountComparison,selectionChanged,setMission,sourceHTML,snapshot,report,activateLayer,hideLayer,inspect,inspectionHTML,updateTelemetry,records,load};
}
